@concat('IF SCHEMA_ID(''m05'') IS NULL EXEC(''CREATE SCHEMA m05'');
IF OBJECT_ID(''m05.attempt'') IS NULL
CREATE TABLE m05.attempt (root_run_id varchar(36) NOT NULL, status varchar(30) NOT NULL,
    batch_id varchar(80) NULL, captured_at_utc datetime2(6) NOT NULL, completed_at_utc datetime2(6) NULL);
IF OBJECT_ID(''m05.guard_facts'') IS NULL
CREATE TABLE m05.guard_facts AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM gold.published_business_bytes WHERE 1=0;
IF OBJECT_ID(''m05.guard_posto'') IS NULL
CREATE TABLE m05.guard_posto AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM (SELECT CAST(posto_sk AS varbinary(8000)) AS posto_sk,CAST(cnpj AS varbinary(8000)) AS cnpj,CAST(revenda_observada AS varbinary(8000)) AS revenda_observada,CAST(bandeira_observada AS varbinary(8000)) AS bandeira_observada,CAST(municipio_ibge AS varbinary(8000)) AS municipio_ibge,CAST(uf AS varbinary(8000)) AS uf,observado_desde,observado_ate FROM gold.dim_posto) AS current_state WHERE 1=0;
IF OBJECT_ID(''m05.guard_publication'') IS NULL
CREATE TABLE m05.guard_publication AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM (SELECT CAST(batch_id AS varbinary(8000)) AS batch_id,CAST(scope_id AS varbinary(8000)) AS scope_id,CAST(source_sha256 AS varbinary(8000)) AS source_sha256,CAST(ibge_sha256 AS varbinary(8000)) AS ibge_sha256,silver_delta_version,is_synthetic,published_at_utc,rows_published,CAST(source_table AS varbinary(8000)) AS source_table,CAST(snapshot_id AS varbinary(8000)) AS snapshot_id FROM gold.publication) AS current_state WHERE 1=0;
IF OBJECT_ID(''m05.guard_calendar'') IS NULL
CREATE TABLE m05.guard_calendar AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM (SELECT data_sk,data,inicio_semana_iso,ano_iso,semana_iso FROM gold.dim_data) AS current_state WHERE 1=0;
IF OBJECT_ID(''m05.guard_municipios'') IS NULL
CREATE TABLE m05.guard_municipios AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM (SELECT CAST(municipio_ibge AS varbinary(8000)) AS municipio_ibge,CAST(nome AS varbinary(8000)) AS nome,CAST(uf AS varbinary(8000)) AS uf FROM gold.dim_municipio) AS current_state WHERE 1=0;
IF OBJECT_ID(''m05.guard_produtos'') IS NULL
CREATE TABLE m05.guard_produtos AS SELECT CAST('''' AS varchar(36)) AS root_run_id, *
FROM (SELECT produto_sk,CAST(produto AS varbinary(8000)) AS produto,CAST(moeda AS varbinary(8000)) AS moeda,CAST(unidade AS varbinary(8000)) AS unidade FROM gold.dim_produto) AS current_state WHERE 1=0;

DECLARE @root varchar(36) = ''',pipeline().RunId,''';
IF TRY_CONVERT(uniqueidentifier,@root) IS NULL
    THROW 51600, ''Pipeline RunId invalido.'', 1;
IF EXISTS (SELECT 1 FROM m05.attempt WHERE root_run_id=@root)
    THROW 51601, ''Nao sobrescrever baseline de uma tentativa existente.'', 1;
BEGIN TRY
    BEGIN TRANSACTION;
    INSERT INTO m05.attempt VALUES (@root,''started'',NULL,CAST(SYSUTCDATETIME() AS datetime2(6)),NULL);
    INSERT INTO m05.guard_facts SELECT @root,* FROM gold.published_business_bytes;
    INSERT INTO m05.guard_posto SELECT @root,* FROM (SELECT CAST(posto_sk AS varbinary(8000)) AS posto_sk,CAST(cnpj AS varbinary(8000)) AS cnpj,CAST(revenda_observada AS varbinary(8000)) AS revenda_observada,CAST(bandeira_observada AS varbinary(8000)) AS bandeira_observada,CAST(municipio_ibge AS varbinary(8000)) AS municipio_ibge,CAST(uf AS varbinary(8000)) AS uf,observado_desde,observado_ate FROM gold.dim_posto) AS current_state;
    INSERT INTO m05.guard_publication SELECT @root,* FROM (SELECT CAST(batch_id AS varbinary(8000)) AS batch_id,CAST(scope_id AS varbinary(8000)) AS scope_id,CAST(source_sha256 AS varbinary(8000)) AS source_sha256,CAST(ibge_sha256 AS varbinary(8000)) AS ibge_sha256,silver_delta_version,is_synthetic,published_at_utc,rows_published,CAST(source_table AS varbinary(8000)) AS source_table,CAST(snapshot_id AS varbinary(8000)) AS snapshot_id FROM gold.publication) AS current_state;
    INSERT INTO m05.guard_calendar SELECT @root,* FROM (SELECT data_sk,data,inicio_semana_iso,ano_iso,semana_iso FROM gold.dim_data) AS current_state;
    INSERT INTO m05.guard_municipios SELECT @root,* FROM (SELECT CAST(municipio_ibge AS varbinary(8000)) AS municipio_ibge,CAST(nome AS varbinary(8000)) AS nome,CAST(uf AS varbinary(8000)) AS uf FROM gold.dim_municipio) AS current_state;
    INSERT INTO m05.guard_produtos SELECT @root,* FROM (SELECT produto_sk,CAST(produto AS varbinary(8000)) AS produto,CAST(moeda AS varbinary(8000)) AS moeda,CAST(unidade AS varbinary(8000)) AS unidade FROM gold.dim_produto) AS current_state;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
SELECT ''m05_baseline_captured'' AS status,@root AS root_run_id;
')

@concat('-- Executar no Warehouse APÓS notebook 07. Alterar somente os três valores abaixo.
DECLARE @lakehouse sysname = ''lh_fuelwatch'';
DECLARE @lakehouse_schema sysname = ''dbo'';
DECLARE @batch_id varchar(80) = ''',json(activity('Export_Gold_Input').output.result.exitValue).batch_id,''';
IF TRY_CONVERT(uniqueidentifier, @batch_id) IS NULL
    THROW 51200, ''Preencher batch_id do JSON m04_transfer_ready.'', 1;
DECLARE @source nvarchar(520) = QUOTENAME(@lakehouse) + ''.'' + QUOTENAME(@lakehouse_schema) + ''.'';
DECLARE @sql nvarchar(max) = N''
BEGIN TRY
    BEGIN TRANSACTION;
    IF (SELECT COUNT_BIG(*) FROM {source}m04_transfer_manifest WHERE batch_id=@batch) <> 1
        THROW 51201, ''''Manifesto nao visivel ou duplicado. Aguardar sync do SQL endpoint.'''', 1;
    IF NOT EXISTS (SELECT 1 FROM {source}m04_transfer_manifest WHERE batch_id=@batch
        AND source_sha256=''''a2c95e5dfa324a9d7253d4e8d53022e0c08dcc5eb6f18551527ee9f29305c54c''''
        AND ibge_sha256=''''2338ca0e4f482e065e14d1aec04d69ba525ba69ec4cc103161f6cb178163dad0''''
        AND silver_delta_version>=0 AND source_table=''''silver_preco_publicado''''
        AND TRY_CONVERT(uniqueidentifier,snapshot_id) IS NOT NULL
        AND is_synthetic=0 AND scope_id=''''anp-2026-1-rj-gasolina''''
        AND expected_rows=8052 AND expected_stations=502 AND expected_municipalities=27 AND expected_unusual=26)
        THROW 51202, ''''Manifesto fora do baseline M02 aprovado.'''', 1;
    IF (SELECT COUNT_BIG(*) FROM {source}m04_transfer_coletas WHERE batch_id=@batch) <> 8052
        OR (SELECT COUNT_BIG(*) FROM {source}m04_transfer_municipios WHERE batch_id=@batch) <> 92
        OR (SELECT COUNT_BIG(*) FROM {source}m04_transfer_calendar WHERE batch_id=@batch) <> 181
        OR (SELECT COUNT_BIG(*) FROM {source}m04_transfer_expected_posto WHERE batch_id=@batch) <> 518
        OR (SELECT COUNT_BIG(*) FROM {source}m04_transfer_expected_weekly WHERE batch_id=@batch) <> 656
        THROW 51203, ''''Transferencia ainda incompleta no SQL endpoint. Nao publicar.'''', 1;
    DELETE FROM gold.stage_coleta;
    DELETE FROM gold.stage_manifest;
    DELETE FROM gold.dim_data;
    DELETE FROM gold.dim_municipio;
    INSERT INTO gold.stage_coleta
        SELECT cnpj, cnpj_origem, produto, data_coleta, preco_venda, moeda, unidade, uf,
            municipio_ibge, municipio_origem, revenda_observada, bandeira_observada, preco_incomum_iqr
        FROM {source}m04_transfer_coletas WHERE batch_id=@batch;
    INSERT INTO gold.stage_manifest
        SELECT batch_id, scope_id, source_sha256, ibge_sha256, silver_delta_version, is_synthetic,
            expected_rows, expected_stations, expected_municipalities, expected_unusual, source_table, snapshot_id
        FROM {source}m04_transfer_manifest WHERE batch_id=@batch;
    INSERT INTO gold.dim_data SELECT data_sk, data, inicio_semana_iso, ano_iso, semana_iso
        FROM {source}m04_transfer_calendar WHERE batch_id=@batch;
    INSERT INTO gold.dim_municipio SELECT municipio_ibge, nome, uf
        FROM {source}m04_transfer_municipios WHERE batch_id=@batch;
    IF EXISTS (SELECT * FROM gold.stage_business_bytes EXCEPT
        SELECT CAST(cnpj AS varbinary(8000)), CAST(cnpj_origem AS varbinary(8000)), CAST(produto AS varbinary(8000)),
            data_coleta, preco_venda, CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)),
            CAST(uf AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(municipio_origem AS varbinary(8000)),
            CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), preco_incomum_iqr
        FROM {source}m04_transfer_coletas WHERE batch_id=@batch)
        THROW 51204, ''''Valores do stage divergem da transferencia.'''', 1;
    IF (SELECT COUNT_BIG(*) FROM gold.stage_coleta) <> 8052 OR EXISTS (
        SELECT cnpj, produto, data_coleta, unidade FROM gold.stage_coleta
        GROUP BY cnpj, produto, data_coleta, unidade HAVING COUNT_BIG(*) <> 1)
        THROW 51205, ''''Cardinalidade do stage divergiu.'''', 1;
    DELETE FROM gold.expected_posto;
    DELETE FROM gold.expected_weekly;
    INSERT INTO gold.expected_posto
        SELECT posto_sk, cnpj, revenda_observada, bandeira_observada, municipio_ibge, uf, observado_desde, observado_ate
        FROM {source}m04_transfer_expected_posto WHERE batch_id=@batch;
    INSERT INTO gold.expected_weekly
        SELECT inicio_semana_iso, ano_iso, semana_iso, municipio_ibge, produto, moeda, unidade,
            coletas, postos_observados, soma_precos, preco_minimo, preco_maximo, precos_incomuns
        FROM {source}m04_transfer_expected_weekly WHERE batch_id=@batch;
    COMMIT TRANSACTION;
    SELECT ''''m04_stage_ready'''' AS status, * FROM gold.stage_manifest;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;'';
SET @sql = REPLACE(@sql, ''{source}'', @source);
EXEC sp_executesql @sql, N''@batch varchar(80)'', @batch=@batch_id;
')

@concat('DECLARE @root varchar(36) = ''',pipeline().RunId,''';
IF TRY_CONVERT(uniqueidentifier,@root) IS NULL
    THROW 51600, ''Pipeline RunId invalido.'', 1;
DECLARE @batch varchar(80) = ''',json(activity('Export_Gold_Input').output.result.exitValue).batch_id,''';
DECLARE @fault varchar(20) = ''',pipeline().parameters.p_fault_stage,''';
IF TRY_CONVERT(uniqueidentifier,@batch) IS NULL OR @fault NOT IN (''none'',''silver'',''gold'')
    THROW 51604, ''Parametros de publicacao invalidos.'', 1;
IF NOT EXISTS (SELECT 1 FROM m05.attempt WHERE root_run_id=@root)
    THROW 51602, ''Baseline ausente.'', 1;
DECLARE @inject bit = CASE WHEN @fault=''gold'' THEN 1 ELSE 0 END;
BEGIN TRY
    EXEC gold.publish_gold @batch_id=@batch,@inject_fail_before_commit=@inject;
    UPDATE m05.attempt SET status=''published'',batch_id=@batch WHERE root_run_id=@root;
END TRY
BEGIN CATCH
    UPDATE m05.attempt SET status=''gold_failed'',batch_id=@batch WHERE root_run_id=@root;
    THROW;
END CATCH;
')

@concat('DECLARE @root varchar(36) = ''',pipeline().RunId,''';
IF TRY_CONVERT(uniqueidentifier,@root) IS NULL
    THROW 51600, ''Pipeline RunId invalido.'', 1;
IF EXISTS (SELECT CAST(posto_sk AS varbinary(8000)), CAST(cnpj AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(uf AS varbinary(8000)), observado_desde, observado_ate FROM gold.dim_posto EXCEPT SELECT CAST(posto_sk AS varbinary(8000)), CAST(cnpj AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(uf AS varbinary(8000)), observado_desde, observado_ate FROM gold.expected_posto) OR EXISTS (SELECT CAST(posto_sk AS varbinary(8000)), CAST(cnpj AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(uf AS varbinary(8000)), observado_desde, observado_ate FROM gold.expected_posto EXCEPT SELECT CAST(posto_sk AS varbinary(8000)), CAST(cnpj AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(uf AS varbinary(8000)), observado_desde, observado_ate FROM gold.dim_posto) OR EXISTS (SELECT inicio_semana_iso, ano_iso, semana_iso, CAST(municipio_ibge AS varbinary(8000)), CAST(produto AS varbinary(8000)), CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), coletas, postos_observados, soma_precos, preco_minimo, preco_maximo, precos_incomuns FROM gold.preco_semanal EXCEPT SELECT inicio_semana_iso, ano_iso, semana_iso, CAST(municipio_ibge AS varbinary(8000)), CAST(produto AS varbinary(8000)), CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), coletas, postos_observados, soma_precos, preco_minimo, preco_maximo, precos_incomuns FROM gold.expected_weekly) OR EXISTS (SELECT inicio_semana_iso, ano_iso, semana_iso, CAST(municipio_ibge AS varbinary(8000)), CAST(produto AS varbinary(8000)), CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), coletas, postos_observados, soma_precos, preco_minimo, preco_maximo, precos_incomuns FROM gold.expected_weekly EXCEPT SELECT inicio_semana_iso, ano_iso, semana_iso, CAST(municipio_ibge AS varbinary(8000)), CAST(produto AS varbinary(8000)), CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), coletas, postos_observados, soma_precos, preco_minimo, preco_maximo, precos_incomuns FROM gold.preco_semanal) OR EXISTS (SELECT CAST(cnpj AS varbinary(8000)), CAST(cnpj_origem AS varbinary(8000)), CAST(produto AS varbinary(8000)), data_coleta, preco_venda, CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), CAST(uf AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(municipio_origem AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), preco_incomum_iqr FROM gold.business_published EXCEPT SELECT CAST(cnpj AS varbinary(8000)), CAST(cnpj_origem AS varbinary(8000)), CAST(produto AS varbinary(8000)), data_coleta, preco_venda, CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), CAST(uf AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(municipio_origem AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), preco_incomum_iqr FROM gold.stage_coleta) OR EXISTS (SELECT CAST(cnpj AS varbinary(8000)), CAST(cnpj_origem AS varbinary(8000)), CAST(produto AS varbinary(8000)), data_coleta, preco_venda, CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), CAST(uf AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(municipio_origem AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), preco_incomum_iqr FROM gold.stage_coleta EXCEPT SELECT CAST(cnpj AS varbinary(8000)), CAST(cnpj_origem AS varbinary(8000)), CAST(produto AS varbinary(8000)), data_coleta, preco_venda, CAST(moeda AS varbinary(8000)), CAST(unidade AS varbinary(8000)), CAST(uf AS varbinary(8000)), CAST(municipio_ibge AS varbinary(8000)), CAST(municipio_origem AS varbinary(8000)), CAST(revenda_observada AS varbinary(8000)), CAST(bandeira_observada AS varbinary(8000)), preco_incomum_iqr FROM gold.business_published)
    THROW 51500, ''Gold diverge da referencia integral.'', 1;
IF (SELECT COUNT_BIG(*) FROM gold.business_published) <> 8052
    OR (SELECT COUNT_BIG(*) FROM gold.dim_posto) <> 518 OR (SELECT COUNT_BIG(*) FROM gold.preco_semanal) <> 656
    OR (SELECT SUM(coletas) FROM gold.preco_semanal) <> 8052
    OR (SELECT SUM(soma_precos) FROM gold.preco_semanal) <> CAST(52777.200 AS decimal(38,3))
    OR (SELECT COUNT_BIG(*) FROM gold.publication) <> 1
    THROW 51501, ''Contagens ou publicacao nao reconciliam.'', 1;
IF (SELECT COUNT(DISTINCT cnpj) FROM gold.business_published) <> 502
    OR (SELECT COUNT(DISTINCT municipio_ibge) FROM gold.business_published) <> 27
    OR (SELECT SUM(CAST(preco_incomum_iqr AS bigint)) FROM gold.business_published) <> 26
    THROW 51502, ''Cobertura ou precos incomuns divergiram.'', 1;
IF EXISTS (SELECT 1 FROM gold.fato_preco_coletado f JOIN gold.dim_posto p ON f.posto_sk=p.posto_sk
    JOIN gold.dim_data d ON f.data_sk=d.data_sk WHERE d.data < p.observado_desde
    OR (p.observado_ate IS NOT NULL AND d.data >= p.observado_ate))
    THROW 51503, ''Associacao temporal invalida.'', 1;
IF EXISTS (SELECT 1 FROM gold.preco_semanal
    WHERE ABS(preco_medio - soma_precos / CAST(coletas AS decimal(18,0))) > CAST(0.000001 AS decimal(10,6)))
    THROW 51504, ''Media semanal nao reconciliou.'', 1;
IF EXISTS (SELECT 1 FROM gold.dim_data WHERE semana_iso <> DATEPART(ISO_WEEK, data)
    OR ano_iso <> YEAR(DATEADD(day,3,inicio_semana_iso))
    OR data_sk <> YEAR(data)*10000+MONTH(data)*100+DAY(data)
    OR DATEDIFF(day,CAST(''1900-01-01'' AS date),inicio_semana_iso) % 7 <> 0
    OR data < inicio_semana_iso OR data >= DATEADD(day,7,inicio_semana_iso))
    THROW 51505, ''Calendario ISO invalido.'', 1;
SELECT ''m04_gold_snapshot_validated'' AS status, batch_id, scope_id, source_table, snapshot_id, source_sha256, ibge_sha256,
    silver_delta_version, is_synthetic, rows_published AS observations,
    502 AS stations, 27 AS municipalities, 26 AS unusual_prices, 518 AS station_versions,
    656 AS weekly_groups, 13 AS business_columns_compared, CAST(1 AS bit) AS full_row_comparison_passed,
    CAST(SYSUTCDATETIME() AS datetime2(6)) AS checked_at_utc
FROM gold.publication FOR JSON PATH, WITHOUT_ARRAY_WRAPPER;

IF NOT EXISTS (SELECT 1 FROM m05.attempt a JOIN gold.publication p ON a.batch_id=p.batch_id
    WHERE a.root_run_id=@root AND a.status=''published'')
    THROW 51605, ''Lote publicado nao corresponde a tentativa.'', 1;
UPDATE m05.attempt SET status=''validated'',completed_at_utc=CAST(SYSUTCDATETIME() AS datetime2(6))
    WHERE root_run_id=@root;
SELECT ''m05_gold_attempt_validated'' AS status,* FROM m05.attempt WHERE root_run_id=@root;
')
